<x-academic-layout title="Notificaciones"><x-academic-header title="Notificaciones" /><section class="academic-intro page-heading"><div><h1>Notificaciones</h1><p>Tus recordatorios y las novedades del instituto.</p></div><a class="academic-link" href="{{ route('board.index') }}">Ver cartelera →</a></section><section class="academic-panel"><form method="GET" class="m04-filters"><label for="state">Estado</label><select id="state" name="state"><option value="">Todas</option><option value="unread" @selected(($filters['state'] ?? '') === 'unread')>Sin leer</option><option value="read" @selected(($filters['state'] ?? '') === 'read')>Leídas</option></select><label for="type">Tipo</label><select id="type" name="type"><option value="">Todos</option><option value="reminder" @selected(($filters['type'] ?? '') === 'reminder')>Recordatorios</option><option value="board" @selected(($filters['type'] ?? '') === 'board')>Cartelera</option></select><button class="button secondary" type="submit">Filtrar</button></form><form method="POST" action="{{ route('inbox.read-all') }}">@csrf<button class="academic-link read-all" type="submit">Marcar todas como leídas</button></form>
